import * as React from 'react'

import './strength-meter.css'

export type StrengthMeterProps = {
    /** 0 (none) to 4 (strong). */
    score: 0 | 1 | 2 | 3 | 4
    /** Accessible name, e.g. "Password strength". */
    label?: string
    /** Text for each score, also shown under the meter. */
    levels?: [string, string, string, string, string]
    className?: string
}

const DEFAULT_LEVELS: [string, string, string, string, string] = ['Too short', 'Weak', 'Fair', 'Good', 'Strong']
const COLORS = ['#71717a', '#ef4444', '#f59e0b', '#22c55e', '#10b981']

// role="meter" with the level as aria-valuetext, so it reads "Strong", not "4".
// The level is also written out in text: colour is never the only signal.
const StrengthMeter = ({ score, label = 'Strength', levels = DEFAULT_LEVELS, className }: StrengthMeterProps) => (
    <div className={['rad-fx-strength', className].filter(Boolean).join(' ')} style={{ '--rad-fx-strength-color': COLORS[score] } as React.CSSProperties}>
        <div
            role="meter"
            aria-label={label}
            aria-valuemin={0}
            aria-valuemax={4}
            aria-valuenow={score}
            aria-valuetext={levels[score]}
            className="rad-fx-strength-bars"
        >
            {[1, 2, 3, 4].map((step) => (
                <span key={step} className="rad-fx-strength-bar" data-on={step <= score ? '' : undefined} />
            ))}
        </div>
        <p className="rad-fx-strength-text" aria-hidden="true">{levels[score]}</p>
    </div>
)

export default StrengthMeter

.rad-fx-strength-bars {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 6px;
}

.rad-fx-strength-bar {
    height: 6px;
    border-radius: 999px;
    background: rgb(127, 127, 127, 0.25);
    overflow: hidden;
    position: relative;
}

.rad-fx-strength-bar::after {
    content: '';
    position: absolute;
    inset: 0;
    background: var(--rad-fx-strength-color);
    transform: scaleX(0);
    transform-origin: 0 50%;
    transition: transform 350ms cubic-bezier(0.3, 0.8, 0.2, 1), background 300ms ease;
}

.rad-fx-strength-bar[data-on]::after { transform: scaleX(1); }

/* Each bar fills just after the one before it. */
.rad-fx-strength-bar:nth-child(2)::after { transition-delay: 60ms; }
.rad-fx-strength-bar:nth-child(3)::after { transition-delay: 120ms; }
.rad-fx-strength-bar:nth-child(4)::after { transition-delay: 180ms; }

.rad-fx-strength-text {
    margin: 8px 0 0;
    font-size: 0.85rem;
    font-weight: 600;
}

@media (prefers-reduced-motion: reduce) {
    .rad-fx-strength-bar::after { transition: none; }
}

[data-rad-fx-motion='reduce'] .rad-fx-strength-bar::after { transition: none; }
